// @generated by:gauntlet run:godseye-local-inngest
import { randomUUID } from "node:crypto";
import { once } from "node:events";
import { mkdtemp, rm } from "node:fs/promises";
import { createServer } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { InfrastructureEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { afterEach, describe, expect, it } from "vitest";
import { z } from "zod";
import { prepareLocalInngest } from "../apps/control-api/src/inngest-runtime.js";
import { appCookie, appTestIdentity } from "./backend-fixture.js";
import { type InfrastructureFixture, infrastructureFixture } from "./infra-helpers.js";
import { inputCell } from "./inngest-runtime-fixture.js";

describe("main control store cell preparation", () => {
  let fixture: InfrastructureFixture | undefined;
  let root: string | undefined;
  let runtime: Awaited<ReturnType<typeof prepareLocalInngest>> | undefined;
  afterEach(async () => {
    await runtime?.close();
    runtime = undefined;
    await fixture?.store.close();
    fixture = undefined;
    if (root) await rm(root, { recursive: true, force: true });
    root = undefined;
  });

  async function setup() {
    fixture = await infrastructureFixture();
    root = await mkdtemp(join(tmpdir(), "godseye-main-inngest-"));
    const active = fixture;
    const directory = root;
    const cell = {
      ...inputCell(),
      projectId: active.project.id,
      environmentId: active.development.id,
    };
    const cells: [typeof cell] = [cell];
    const configuration = {
      enabled: true,
      registrationEnabled: true,
      allowedOrigins: ["http://localhost:4731"],
      maxFileMiB: 8,
      storageMiB: 32,
      maxFiles: 10,
      eventRetention: 100,
    };
    await active.core.configureBackend(
      { ...active.freshOwner(), authenticatedAt: new Date().toISOString() },
      active.project.id,
      active.development.id,
      {
        expectedRevision: 0,
        expectedProjectRevision: active.project.revision,
        expectedEnvironmentRevision: active.development.revision,
        configuration,
      },
      randomUUID(),
    );
    const options = {
      store: active.store,
      rootDirectory: join(directory, "applications"),
      stateDirectory: join(directory, "state"),
      cells,
      now: active.clock.now,
    };
    return { fixture: active, options, cells, configuration };
  }

  it("T-E06-R02 refuses nonexistent or foreign owner cells before any listener or engine can start", async () => {
    const { options, fixture } = await setup();
    await expect(
      prepareLocalInngest({
        ...options,
        cells: [
          {
            ...options.cells[0],
            projectId: fixture.secondProject.id,
            environmentId: fixture.development.id,
          },
        ],
      }),
    ).rejects.toBeInstanceOf(Error);
    await expect(
      prepareLocalInngest({
        ...options,
        cells: [{ ...options.cells[0], projectId: randomUUID(), environmentId: randomUUID() }],
      }),
    ).rejects.toBeInstanceOf(Error);
  });

  it("T-E06-R02 composes the native registry with the existing owner jobs store and closes idempotently", async () => {
    const { options, fixture } = await setup();
    runtime = await prepareLocalInngest(options);
    const infrastructure = new InfrastructureEngine(fixture.store, {
      ...fixture.configuration,
      jobs: runtime.jobs,
    });
    runtime.bind(infrastructure);
    expect((await infrastructure.jobs.overview(fixture.freshOwner())).engine.state).toBe(
      "local_inngest",
    );
    expect(runtime.jobs.inngestEnvironmentIds?.has(fixture.development.id)).toBe(true);
    expect((await infrastructure.jobs.overview(fixture.freshOwner())).definitions).toHaveLength(0);

    await runtime.close();
    await runtime.close();
    // Closing a cell runtime must not close the shared owner/control store.
    expect(
      (await fixture.core.listProjects(fixture.freshOwner())).map((project) => project.id),
    ).toContain(fixture.project.id);
  });

  it("T-E06-R02 keeps valid cells reopenable after a later scope is rejected", async () => {
    const { options, fixture } = await setup();
    const foreignEnvironment = fixture.secondProject.environments.find(
      (environment) => environment.kind === "development",
    );
    if (!foreignEnvironment) throw new Error("Foreign runtime fixture environment missing");
    await expect(
      prepareLocalInngest({
        ...options,
        cells: [
          ...options.cells,
          {
            ...inputCell(1),
            projectId: fixture.project.id,
            environmentId: foreignEnvironment.id,
          },
        ],
      }),
    ).rejects.toBeInstanceOf(Error);

    runtime = await prepareLocalInngest(options);
    expect(runtime.jobs.inngestEnvironmentIds?.has(fixture.development.id)).toBe(true);
  });

  it("T-E06-R02 refuses unbound startup and releases prepared app resources after a listener collision", async () => {
    const { options, fixture } = await setup();
    const occupied = createServer();
    occupied.listen(0, "127.0.0.1");
    await once(occupied, "listening");
    const address = occupied.address();
    if (!address || typeof address === "string") throw new Error("Occupied runtime port missing");
    const configured = { ...options, cells: [{ ...options.cells[0], workerPort: address.port }] };
    try {
      runtime = await prepareLocalInngest(configured);
      const signal = new AbortController().signal;
      await expect(runtime.start({ signal, onFailure: () => undefined })).rejects.toBeInstanceOf(
        Error,
      );
      const infrastructure = new InfrastructureEngine(fixture.store, {
        ...fixture.configuration,
        jobs: runtime.jobs,
      });
      runtime.bind(infrastructure);
      expect(() => runtime?.bind(infrastructure)).toThrow();
      await expect(runtime.start({ signal, onFailure: () => undefined })).rejects.toBeInstanceOf(
        Error,
      );
      await runtime.close();
      await expect(runtime.start({ signal, onFailure: () => undefined })).rejects.toBeInstanceOf(
        Error,
      );
      runtime = await prepareLocalInngest(configured);
      expect(runtime.jobs.inngestEnvironmentIds?.has(fixture.development.id)).toBe(true);
    } finally {
      await new Promise<void>((resolve) => occupied.close(() => resolve()));
    }
  });

  it.runIf(process.env.GODSEYE_INNGEST_LAB === "enabled")(
    "T-E06-R03 runs the main-process composition against the existing owner's store and scopes the trusted application payload",
    async () => {
      const { options, fixture, configuration } = await setup();
      const ports = await Promise.all(
        Array.from({ length: 6 }, async () => {
          const listener = createServer();
          listener.listen(0, "127.0.0.1");
          await once(listener, "listening");
          const address = listener.address();
          if (!address || typeof address === "string")
            throw new Error("Runtime fixture port missing");
          await new Promise<void>((resolve) => listener.close(() => resolve()));
          return address.port;
        }),
      );
      const [
        enginePort,
        workerPort,
        applicationPort,
        gatewayPort,
        gatewayGrpcPort,
        executorGrpcPort,
      ] = ports;
      if (
        !enginePort ||
        !workerPort ||
        !applicationPort ||
        !gatewayPort ||
        !gatewayGrpcPort ||
        !executorGrpcPort
      )
        throw new Error("Six independent runtime ports are required");
      const cell = {
        projectId: fixture.project.id,
        environmentId: fixture.development.id,
        enginePort,
        workerPort,
        applicationPort,
        gatewayPort,
        gatewayGrpcPort,
        executorGrpcPort,
      };
      runtime = await prepareLocalInngest({
        ...options,
        cells: [cell],
        applicationRoutes(registry) {
          registry.post(
            "/publish",
            z.object({ revision: z.number() }),
            z.object({ accepted: z.boolean() }),
            async (context) => {
              await context.emitEvent({
                type: "document.updated",
                payload: { revision: context.input.revision },
                idempotencyKey: "main-runtime-publication",
              });
              return { accepted: true };
            },
          );
        },
      });
      const infrastructure = new InfrastructureEngine(fixture.store, {
        ...fixture.configuration,
        jobs: runtime.jobs,
      });
      runtime.bind(infrastructure);
      const definition = await infrastructure.jobs.registerDefinition(
        fixture.freshOwner(),
        {
          projectId: fixture.project.id,
          environmentId: fixture.development.id,
          expectedEnvironmentRevision: fixture.development.revision,
          name: "main-runtime-publication",
          handler: "application.archive",
          trigger: { kind: "event", eventType: "document.updated" },
          effectPolicy: "read_only",
          limits: { maxConcurrent: 1, maxAttempts: 1, timeoutSeconds: 10, retentionDays: 7 },
        },
        randomUUID(),
      );
      let failures = 0;
      await runtime.start({
        signal: new AbortController().signal,
        onFailure: () => {
          failures++;
        },
      });
      const baseUrl = `http://127.0.0.1:${applicationPort}/api/app/v1`;
      const headers = {
        "Content-Type": "application/json",
        Origin: `http://127.0.0.1:${applicationPort}`,
        "X-Godseye-Project": fixture.project.id,
        "X-Godseye-Environment": fixture.development.id,
      };
      const registration = await fetch(`${baseUrl}/auth/sign-up/email`, {
        method: "POST",
        headers,
        body: JSON.stringify(appTestIdentity),
      });
      expect(registration.status).toBe(200);
      const response = await fetch(`${baseUrl}/custom/publish`, {
        method: "POST",
        headers: { ...headers, Cookie: appCookie(registration), "Idempotency-Key": randomUUID() },
        body: JSON.stringify({ revision: 71 }),
      });
      expect(response.status).toBe(200);
      const deadline = Date.now() + 45000;
      let completed = false;
      while (Date.now() < deadline) {
        await infrastructure.jobs.tick();
        await infrastructure.foundation.tick("main-inngest-runtime-test");
        await infrastructure.jobs.tick();
        const overview = await infrastructure.jobs.overview(fixture.freshOwner());
        if (
          overview.runs.some(
            (run) => run.definitionId === definition.id && run.state === "succeeded",
          )
        ) {
          completed = true;
          break;
        }
        await new Promise<void>((resolve) => setTimeout(resolve, 100));
      }
      expect(completed).toBe(true);
      expect(failures).toBe(0);
      const overview = await infrastructure.jobs.overview(fixture.freshOwner());
      expect(overview.engine.state).toBe("local_inngest");
      expect(overview.runs).toHaveLength(1);
      expect(overview.runs[0]).toMatchObject({
        projectId: fixture.project.id,
        environmentId: fixture.development.id,
      });
      const [receipt] = await fixture.store.db.select().from(schema.applicationJobEvents);
      if (!receipt) throw new Error("Scoped application event metadata missing");
      const authority = {
        projectId: receipt.projectId,
        environmentId: receipt.environmentId,
        producerId: receipt.producerId,
      };
      expect((await runtime.jobs.applicationEventLoader?.(authority, receipt.id))?.payload).toEqual(
        { revision: 71 },
      );
      expect(
        await runtime.jobs.applicationEventLoader?.(
          { ...authority, producerId: randomUUID() },
          receipt.id,
        ),
      ).toBeUndefined();
      await fixture.core.configureBackend(
        { ...fixture.freshOwner(), authenticatedAt: new Date().toISOString() },
        fixture.project.id,
        fixture.development.id,
        {
          expectedRevision: 1,
          expectedProjectRevision: fixture.project.revision,
          expectedEnvironmentRevision: fixture.development.revision,
          configuration: { ...configuration, enabled: false },
        },
        randomUUID(),
      );
      expect((await fetch(`${baseUrl}/health`, { headers })).status).toBe(423);
      await new Promise<void>((resolve) => setTimeout(resolve, 1100));
      expect(failures).toBe(0);
    },
    120000,
  );
});
